 for(const [k,nome]of [['retrato','Retrato'],['simbolo','Símbolo da organização']]){const n=painel(nome);const img=el('img',{id:'forja-img-'+k,alt:nome,class:'forja-retrato',hidden:true});const arquivo=el('input',{type:'file',id:'forja-arquivo-'+k,accept:'image/png,image/jpeg,image/webp','aria-label':'Escolher '+nome});arquivo.addEventListener('change',()=>tentar(async()=>{const f=arquivo.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>3000000)throw Error('Escolha PNG, JPEG ou WebP de até 3 MB.');const data=await new Promise((ok,no)=>{const leitor=new FileReader();leitor.onload=()=>ok(leitor.result);leitor.onerror=no;leitor.readAsDataURL(f);});const imagem=new Image();imagem.src=data;await imagem.decode();const canvas=document.createElement('canvas'),fator=Math.min(1,800/imagem.width,1000/imagem.height);canvas.width=Math.round(imagem.width*fator);canvas.height=Math.round(imagem.height*fator);canvas.getContext('2d').drawImage(imagem,0,0,canvas.width,canvas.height);const resultado=canvas.toDataURL('image/webp',.8);if(resultado.length>900000)throw Error('Imagem ainda muito grande após reduzir.');detalhesFicha.historia[k]=resultado;preencherHistoria();salvar();}).catch?.(e=>mostrarToast(e.message)));n.append(img,arquivo,botao('Remover '+nome,()=>{detalhesFicha.historia[k]='';arquivo.value='';preencherHistoria();salvar();}));root.append(n);}
